js:
morse.watch('div[contenteditable="true"].ProseMirror', box => {
  morse.on(box, "keydown", e => {
    // Our own re-dispatched event is untrusted: let the editor handle it.
    if (e.key !== "Enter" || e.isComposing || e.shiftKey || !e.isTrusted) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    if (e.ctrlKey || e.metaKey) {
      document.querySelector('button[aria-label="Send message"]')?.click();
    } else {
      box.dispatchEvent(new KeyboardEvent("keydown", {
        key: "Enter", code: "Enter", shiftKey: true, bubbles: true, cancelable: true,
      }));
    }
  }, true);

  const wrap = box.closest("fieldset") || box.parentElement;
  if (getComputedStyle(wrap).position === "static") wrap.style.position = "relative";
  const mac = /Mac/.test(navigator.platform);
  wrap.append(morse.el("div", { class: "morse-send-hint", text: (mac ? "⌘" : "Ctrl") + " + Enter to send" }));
});
